const photos=['32ba496f-6c99-4291-a697-30e75f15adb9.jpeg','538bc964-9fa1-461c-8a3c-80d2f1c3c92a.jpeg','5AAC3E12-A804-467C-BDB9-CDFAD32EC04E.jpeg','64474541-c561-4e68-840f-6e29754da54b.jpeg','7e8fcd3e-2498-46bd-843b-1abe0d62e058.jpeg','945140f9-512d-44b8-922f-b0402a22ce36.jpeg','a0667aae-a3d5-4987-8be2-a26d380c4d79.jpeg','c89f7fb7-77d5-4ab0-990e-1d42c2282c4a.jpeg','df85c2ae-edaf-47bd-9a6b-236568703636.jpeg','IMG_1347.jpeg','IMG_2184.jpeg'];
const captions=['Even with cucumber slices over your eyes, you are my favorite person.','Your eyes make my heart melt every time.','That little pout is just too cute.','Your smile makes even an ordinary day brighter.','Every mirror selfie makes me fall for you a little more.','Your wink makes me smile every time.','I am so in love with that smile.','Even with miles between us, you are always on my mind.','Even while I am fishing, I am thinking of you.','My phone wallpaper reminds me just how much I love you.','I am so in love with you that you are even on my lock screen.'];
const grid=document.querySelector('#galleryGrid');function renderGallery(){grid.innerHTML='';photos.forEach((src,i)=>{const card=document.createElement('button');card.className='memory';card.type='button';card.setAttribute('aria-label',`View memory ${i+1}`);card.innerHTML=`<img src="${src}" alt="A favorite photo" loading="lazy"><span class="sr-only">${captions[i]}</span>`;card.addEventListener('click',()=>openPhoto(i));grid.append(card)})}renderGallery();
const lightbox=document.querySelector('#lightbox'),lbImg=lightbox.querySelector('img'),lbCaption=lightbox.querySelector('p');let current=0;function openPhoto(i){current=i;lbImg.src=photos[i];lbCaption.textContent=captions[i];lightbox.classList.add('open');lightbox.setAttribute('aria-hidden','false');document.body.style.overflow='hidden'}function closePhoto(){lightbox.classList.remove('open');lightbox.setAttribute('aria-hidden','true');document.body.style.overflow=''}function stepPhoto(n){openPhoto((current+n+photos.length)%photos.length)}lightbox.querySelector('.lightbox-close').onclick=closePhoto;lightbox.querySelector('.lightbox-prev').onclick=()=>stepPhoto(-1);lightbox.querySelector('.lightbox-next').onclick=()=>stepPhoto(1);lightbox.addEventListener('click',e=>{if(e.target===lightbox)closePhoto()});document.addEventListener('keydown',e=>{if(!lightbox.classList.contains('open'))return;if(e.key==='Escape')closePhoto();if(e.key==='ArrowLeft')stepPhoto(-1);if(e.key==='ArrowRight')stepPhoto(1)});
document.querySelector('#shuffleBtn').addEventListener('click',()=>{photos.sort(()=>Math.random()-.5);renderGallery()});document.querySelector('#sealBtn').addEventListener('click',()=>{const toast=document.querySelector('#toast');toast.classList.add('show');for(let i=0;i<18;i++){const h=document.createElement('span');h.textContent=['♥','♡','✦'][i%3];h.style.cssText=`position:fixed;z-index:60;left:${40+Math.random()*20}%;top:65%;color:${['#d97c78','#b45d68','#efbd9f'][i%3]};font-size:${12+Math.random()*24}px;pointer-events:none;animation:kiss 1.8s ease-out forwards`;document.body.append(h);setTimeout(()=>h.remove(),1900)}setTimeout(()=>toast.classList.remove('show'),2200)});
document.head.insertAdjacentHTML('beforeend','<style>@keyframes kiss{to{transform:translate(${Math.random()*240-120}px,-260px) rotate(40deg) scale(.3);opacity:0}}</style>');
const sections=[...document.querySelectorAll('main section[id]')],navLinks=[...document.querySelectorAll('.nav-link')];const observer=new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting){navLinks.forEach(a=>a.classList.toggle('active',a.hash===`#${entry.target.id}`))}}),{rootMargin:'-35% 0px -55% 0px'});sections.forEach(s=>observer.observe(s));
// Ambient drifting hearts and a tiny sparkle trail make the page feel alive.
const reduceMotion=matchMedia('(prefers-reduced-motion: reduce)').matches;
if(!reduceMotion){const sky=document.querySelector('.ambient-hearts');for(let i=0;i<13;i++){const h=document.createElement('span');h.className='ambient-heart';h.textContent=i%3===0?'✦':(i%2?'♡':'♥');h.style.left=`${4+Math.random()*92}%`;h.style.bottom=`-${Math.random()*45}vh`;h.style.setProperty('--duration',`${13+Math.random()*16}s`);h.style.setProperty('--delay',`${-Math.random()*24}s`);h.style.setProperty('--sway',`${Math.random()*100-50}px`);h.style.fontSize=`${10+Math.random()*15}px`;sky.append(h)}
 let lastTrail=0;document.addEventListener('pointermove',e=>{if(e.pointerType==='touch'||performance.now()-lastTrail<75)return;lastTrail=performance.now();const s=document.createElement('span');s.className='cursor-spark';s.textContent=Math.random()>.45?'♡':'✦';s.style.left=`${e.clientX}px`;s.style.top=`${e.clientY}px`;s.style.setProperty('--dx',`${Math.random()*40-20}px`);s.style.setProperty('--dy',`${-14-Math.random()*26}px`);s.style.setProperty('--size',`${9+Math.random()*10}px`);document.body.append(s);setTimeout(()=>s.remove(),950)},{passive:true});
 let scheduled=false;addEventListener('scroll',()=>{if(scheduled)return;scheduled=true;requestAnimationFrame(()=>{const max=document.documentElement.scrollHeight-innerHeight;document.querySelector('.scroll-progress span').style.transform=`scaleX(${max>0?scrollY/max:0})`;scheduled=false})},{passive:true});
 // Gentle tilt on larger screens; the card never moves enough to obscure its text.
 if(matchMedia('(pointer:fine)').matches){document.querySelectorAll('.reason-card').forEach(card=>{card.addEventListener('pointermove',e=>{const r=card.getBoundingClientRect(),x=(e.clientX-r.left)/r.width-.5,y=(e.clientY-r.top)/r.height-.5;card.style.transform=`perspective(700px) rotateX(${-y*3}deg) rotateY(${x*3}deg) translateY(-5px)`});card.addEventListener('pointerleave',()=>card.style.removeProperty('transform'))})}}
